using Microsoft.EntityFrameworkCore;
using Osynix.Ats.Data;
using Osynix.Ats.Domain;
namespace Osynix.Ats.Services;
public record RecruiterListing(string Id,string Name,string Headline,string Skills,string Bio,string Location,int YearsExperience,string Availability);
public record RecruiterDetail(string Id,string Name,string Image,FreelancerProfile Profile);
public class FreelancerDirectory(Access access,EmployerTeamService teams,IDbContextFactory<AtsDbContext> factory){
 public async Task<RecruiterDetail> Details(string id){await teams.Team();await using var db=await factory.CreateDbContextAsync();var p=await db.FreelancerProfiles.AsNoTracking().SingleOrDefaultAsync(p=>p.UserId==id&&p.Published)??throw new InvalidOperationException("This freelancer is no longer listed.");var u=await db.Users.AsNoTracking().SingleOrDefaultAsync(u=>u.Id==id&&u.AccountType==AccountTypes.Freelance&&u.EmailConfirmed&&u.Status=="Active")??throw new InvalidOperationException("This freelancer is unavailable.");return new(u.Id,u.FullName,SelfProfileService.ImageUrl(u),p);}
 public async Task<FreelancerProfile?> MyProfile(){var id=await access.UserId();await using var db=await factory.CreateDbContextAsync();var account=await db.Users.FindAsync(id);if(account?.AccountType!=AccountTypes.Freelance)return null;return await db.FreelancerProfiles.AsNoTracking().SingleOrDefaultAsync(p=>p.UserId==id)??new(){UserId=id};}
 public async Task Save(FreelancerProfile input){var id=await access.UserId();await using var db=await factory.CreateDbContextAsync();if(!await db.Users.AnyAsync(u=>u.Id==id&&u.AccountType==AccountTypes.Freelance&&u.Status=="Active"&&u.EmailConfirmed))throw new UnauthorizedAccessException();if(input.Headline.Length>160||input.Skills.Length>1000||input.Bio.Length>3000||input.Location.Length>150||input.YearsExperience is <0 or >70||input.Availability is not("Available" or "Limited Availability" or "Not Available"))throw new InvalidOperationException("Review Your Profile Lengths, Experience And Availability.");if(input.Published&&(string.IsNullOrWhiteSpace(input.Headline)||string.IsNullOrWhiteSpace(input.Skills)||string.IsNullOrWhiteSpace(input.Bio)))throw new InvalidOperationException("Add A Headline, Specialisms And Introduction Before Publishing.");var saved=await db.FreelancerProfiles.SingleOrDefaultAsync(p=>p.UserId==id);if(saved is null){saved=new(){UserId=id};db.Add(saved);}else if(saved.Revision!=input.Revision)throw new InvalidOperationException("Your Profile Changed. Reload Before Saving.");saved.Published=input.Published;saved.Headline=input.Headline.Trim();saved.Skills=input.Skills.Trim();saved.Bio=input.Bio.Trim();saved.Location=input.Location.Trim();saved.YearsExperience=input.YearsExperience;saved.Availability=input.Availability;AtsService.Audit(db,id,"Freelancer directory profile updated",saved.Id.ToString());await db.SaveChangesAsync();}
 public async Task<List<RecruiterListing>> Search(){await teams.Team();await using var db=await factory.CreateDbContextAsync();return await (from p in db.FreelancerProfiles.AsNoTracking() join u in db.Users on p.UserId equals u.Id where p.Published&&u.AccountType==AccountTypes.Freelance&&u.Status=="Active"&&u.EmailConfirmed orderby u.FullName select new RecruiterListing(u.Id,u.FullName,p.Headline,p.Skills,p.Bio,p.Location,p.YearsExperience,p.Availability)).ToListAsync();}
 public async Task<ForwardResult> Invite(string id){await teams.Team();await using var db=await factory.CreateDbContextAsync();var profile=await db.FreelancerProfiles.AsNoTracking().SingleOrDefaultAsync(p=>p.UserId==id&&p.Published)??throw new InvalidOperationException("This Recruiter Is No Longer Listed.");var user=await db.Users.SingleAsync(u=>u.Id==id);if(user.AccountType!=AccountTypes.Freelance||user.Status!="Active"||!user.EmailConfirmed)throw new InvalidOperationException("This Recruiter Is Unavailable.");return await teams.Invite(user.FullName,user.Email!);}
}
